def compute(goal, nums):
    # bottom-up tabulated DP (coin change style)
    table = [float('inf')] * (goal + 1)
    table[0] = 0
    for idx in range(1, goal + 1):
        for coin in nums:
            if coin <= idx:
                table[idx] = min(table[idx], table[idx - coin] + 1)
    return table[goal] if table[goal] != float('inf') else -1

